const rel = (items) => items.map((x) => `<a class="cat-card" href="${x.h}" data-reveal><h3>${x.t}</h3><p>${x.p}</p><span class="more">Открыть</span></a>`).join("");

function page(p) {
  const crumbs = p.crumbs.map((c, i) => i < p.crumbs.length - 1 ? `<a href="${c.h}">${c.t}</a> / ` : c.t).join("");
  const paras = (p.p || []).map((t) => `<p>${t}</p>`).join("");
  const lis = (p.includes || []).map((t) => `<li>${t}</li>`).join("");
  const steps = (p.steps || []).map((s, i) => `<article class="step" data-reveal><div class="step__n">0${i + 1}</div><h3>${s.t}</h3><p>${s.p}</p></article>`).join("");
  const faq = (p.faq || []).map((f, i) => `<article class="acc__item${i ? "" : " is-open"}"><button class="acc__btn" type="button">${f.q}<i>+</i></button><div class="acc__panel"><div><p>${f.a}</p></div></div></article>`).join("");
  const atlas = p.atlas ? `<section class="wrap"><h2 class="section-title" data-reveal>${p.atlasTitle || "На этом маршруте"}</h2><div class="atlas">${p.atlas.map((a) => `<a href="${a.h}" data-reveal><span>${a.s}</span><h3>${a.t}</h3><p>${a.p}</p></a>`).join("")}</div></section>` : "";
  return HDR.replace("__TITLE__", p.title).replace("__DESC__", p.desc) + `
  <main>
    <section class="page-hero wrap">
      <div class="page-hero__box">
        <div>
          <div class="crumb"><a href="index.html">Главная</a> / ${crumbs}</div>
          <h1 class="split">${p.h1}</h1>
        </div>
        <p>${p.lead}</p>
      </div>
    </section>
    <section class="svc wrap">
      <div data-reveal>
        <img class="article-cover" src="${p.img || "images/clinic-consult.jpg"}" alt="" loading="lazy">
        ${paras}
        <h2>Что входит</h2>
        <ul>${lis}</ul>
        ${p.note ? `<div class="note">${p.note}</div>` : ""}
      </div>
      <aside class="svc-side" data-reveal>
        <span>Стоимость</span>
        <b>${p.price}</b>
        <em>${p.priceNote || "после осмотра врача"}</em>
        <a class="btn btn--dark" href="#" data-open-modal>Записаться <span class="arr"><svg viewBox="0 0 14 14" fill="none"><path d="M3 7h8M8 3l4 4-4 4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg></span></a>
        <a class="btn btn--line" href="tel:+73812901212" data-city-tel>Позвонить</a>
        <p>18+. Добровольно. Имеются противопоказания.</p>
      </aside>
    </section>
    ${atlas}
    ${p.extra || ""}
    <section class="steps wrap">
      <h2 class="section-title" data-reveal>Как это проходит</h2>
      <div class="steps__grid">${steps}</div>
    </section>
    <section class="faq wrap">
      <div data-reveal><h2 class="section-title">Вопросы<br>по программе</h2></div>
      <div class="acc" data-acc data-reveal>${faq}</div>
    </section>
    <section class="wrap">
      <h2 class="section-title" data-reveal>Рядом по маршруту</h2>
      <div class="related">${rel(p.related)}</div>
    </section>
    <section class="cta wrap">
      <div class="cta__box" data-reveal="scale">
        <div><h2>${p.cta || "Подскажем, эта ли программа"}</h2><p>Дежурный врач на связи 24/7. Можно не называть имя.</p></div>
        <a class="btn btn--light" href="#" data-open-modal>Записаться <span class="arr"><svg viewBox="0 0 14 14" fill="none"><path d="M3 7h8M8 3l4 4-4 4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg></span></a>
      </div>
    </section>
  </main>
` + FTR;
}

